const $ = id => document.getElementById(id);
const textNodes = [...document.querySelectorAll('[data-copy]')], htmlNodes = [...document.querySelectorAll('[data-html]')], ariaNodes = [...document.querySelectorAll('[data-aria]')];
const acts = [...document.querySelectorAll('[data-act]')], chapterLinks = [...document.querySelectorAll('.chapter-index a')];
const reduced = matchMedia('(prefers-reduced-motion:reduce)'), narrow = matchMedia('(max-width:650px)');
let language='en', paused=false, ready=false, failed=false, seed=42, feedbackKey='', chapter=0, targetProgress=0, currentProgress=0, scrollFraction=0, raf=0, clock=0, lastStamp=0, disposed=false;
const MAX_PULSES=32, PULSE_DURATION=3.2;
const pulseStarts=new Float64Array(MAX_PULSES), pulseAges=new Float32Array(MAX_PULSES);
let pulseCount=0;
function updatePulses(){
 let kept=0;
 for(let i=0;i<pulseCount;i++){
  const age=clock-pulseStarts[i];
  if(age>=0&&age<PULSE_DURATION){pulseStarts[kept]=pulseStarts[i];pulseAges[kept]=age;kept++;}
 }
 pulseCount=kept;
}
function emitPulse(previewAge=0){
 updatePulses();
 if(pulseCount===MAX_PULSES)return false;
 pulseStarts[pulseCount]=clock-previewAge;pulseAges[pulseCount]=previewAge;pulseCount++;
 return true;
}
function clearPulses(){pulseCount=0;}
let sceneApi=null;
const metrics=[0,1,2,3];
const pointer={x:0,y:0}, smoothedPointer={x:0,y:0};
function initialLanguage(){const q=new URL(location.href).searchParams.get('lang');if(Object.hasOwn(translations,q))return q;try{const saved=localStorage.getItem('ignis-language');if(Object.hasOwn(translations,saved))return saved;}catch{}return navigator.language.startsWith('pt')?'pt':'en';}
function updateStatus(){const d=translations[language];$('render-label').textContent=d[failed?'renderStatic':!ready?'renderLoading':paused||reduced.matches?'renderPaused':'renderLive'];$('motion').setAttribute('aria-pressed',String(paused||reduced.matches));$('motion').setAttribute('aria-label',d[reduced.matches?'reducedMotion':paused?'resume':'pause']);$('motion').disabled=failed||reduced.matches;document.querySelector('.motion-label').textContent=d[reduced.matches?'reducedMotion':paused?'resume':'pause'];document.querySelector('.pause-icon').textContent=paused?'▷':'Ⅱ';$('action-feedback').textContent=feedbackKey?d[feedbackKey]:'';}
