function updateChapter(){chapterLinks.forEach((a,i)=>{a.classList.toggle('active',i===chapter);if(i===chapter)a.setAttribute('aria-current','step');else a.removeAttribute('aria-current');});$('scene-chapter').textContent=`0${chapter+1} / ${translations[language].chapterNames[chapter]}`;}
function measure(){acts.forEach((a,i)=>metrics[i]=a.offsetTop);readScroll();}
function readScroll(){const y=scrollY;chapter=0;for(let i=1;i<metrics.length;i++)if(y+innerHeight*.28>=metrics[i])chapter=i;let base=0;for(let i=1;i<metrics.length;i++)if(y>=metrics[i])base=i;targetProgress=base===3?3:base+(y-metrics[base])/Math.max(1,metrics[base+1]-metrics[base]);scrollFraction=Math.min(1,y/Math.max(1,document.documentElement.scrollHeight-innerHeight));$('progress').style.transform=`scaleX(${scrollFraction})`;$('scene-percentage').textContent=`${String(Math.round(Math.min(1,targetProgress/3)*100)).padStart(3,'0')}%`;document.querySelector('.scene-footer').classList.toggle('hide',targetProgress>2.9);document.body.classList.toggle('at-proof',targetProgress>=2.97);updateChapter();requestRender();}
function requestRender(){if(!disposed&&!document.hidden&&ready&&!raf)raf=requestAnimationFrame(frame);}
function frame(stamp){raf=0;if(disposed||document.hidden||!sceneApi)return;const delta=Math.min(.05,Math.max(0,(stamp-(lastStamp||stamp))/1000));lastStamp=stamp;const moving=!paused&&!reduced.matches&&targetProgress<3; if(moving)clock+=delta;const blend=reduced.matches||paused?1:1-Math.exp(-delta*7);currentProgress+=(targetProgress-currentProgress)*blend;smoothedPointer.x+=(pointer.x-smoothedPointer.x)*blend;smoothedPointer.y+=(pointer.y-smoothedPointer.y)*blend;updatePulses();sceneApi.render(currentProgress,clock,smoothedPointer,pulseAges,pulseCount);if(moving||Math.abs(targetProgress-currentProgress)>.001)requestRender();}
function feedback(key){feedbackKey=key;updateStatus();}
document.querySelectorAll('[data-language]').forEach(b=>b.addEventListener('click',()=>setLanguage(b.dataset.language)));
$('motion').addEventListener('click',()=>{paused=!paused;document.body.classList.toggle('motion-paused',paused);lastStamp=0;updateStatus();requestRender();});
$('ignite').addEventListener('click',()=>{const emitted=emitPulse(reduced.matches||paused?1.2:0);feedback(emitted?'pulseSent':'pulseLimit');requestRender();});
$('regenerate').addEventListener('click',()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;seed=seed%10000;sceneApi?.regenerate(seed);$('seed-value').textContent=String(seed).padStart(4,'0');clearPulses();emitPulse(.2);feedback('worldCreated');requestRender();});
$('wireframe').addEventListener('click',()=>{const value=$('wireframe').getAttribute('aria-pressed')!=='true';$('wireframe').setAttribute('aria-pressed',String(value));sceneApi?.wireframe(value);feedback(value?'wireOn':'wireOff');requestRender();});
$('reset').addEventListener('click',()=>{seed=42;sceneApi?.regenerate(seed);sceneApi?.wireframe(false);$('wireframe').setAttribute('aria-pressed','false');$('seed-value').textContent='0042';clearPulses();pointer.x=pointer.y=0;feedback('worldReset');requestRender();});
addEventListener('scroll',readScroll,{passive:true});addEventListener('resize',()=>{measure();sceneApi?.resize();requestRender();},{passive:true});
addEventListener('pointermove',e=>{if(e.target.closest('button,a'))return;pointer.x=e.clientX/innerWidth*2-1;pointer.y=1-e.clientY/innerHeight*2;requestRender();},{passive:true});
addEventListener('pointerleave',()=>{pointer.x=pointer.y=0;requestRender();});
document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelAnimationFrame(raf);raf=0;}else{lastStamp=0;requestRender();}});
reduced.addEventListener('change',()=>{lastStamp=0;updateStatus();requestRender();});
mountEngineChapters(measure);
setLanguage(initialLanguage(),false);
if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in-view');observer.unobserve(e.target);}}),{threshold:.12});document.querySelectorAll('.proof-title,.proof-layout,.reality-note').forEach(n=>{n.classList.add('reveal-line');observer.observe(n);});}
function fail(){failed=true;ready=false;cancelAnimationFrame(raf);raf=0;document.body.classList.remove('webgl');document.body.classList.add('webgl-failed');document.querySelectorAll('.console-controls button').forEach(b=>b.disabled=true);$('motion').disabled=true;updateStatus();sceneApi?.dispose();sceneApi=null;}
